style.css:
@-moz-document domain("pintrest.com") {
/* =========================
       ? COLORS
       ========================= */

    :root {
        --purple: #9b7be8;
        --purple-dark: #7655c7;
        --purple-light: #d9ccfa;
        --purple-pale: #f4f0ff;
        --white: #ffffff;
    }


    /* =========================
       ? CHECKERBOARD BACKGROUND
       ========================= */

    html,
    body {
        background-color: #faf8ff !important;

        background-image:
            linear-gradient(
                45deg,
                rgba(155, 123, 232, 0.20) 25%,
                transparent 25%,
                transparent 75%,
                rgba(155, 123, 232, 0.20) 75%
            ),
            linear-gradient(
                45deg,
                rgba(155, 123, 232, 0.20) 25%,
                transparent 25%,
                transparent 75%,
                rgba(155, 123, 232, 0.20) 75%
            ) !important;

        background-size: 112px 112px !important;
        background-position: 0 0, 56px 56px !important;
        background-attachment: fixed !important;
    }


    /* =========================
       ? MAIN TIKTOK AREAS
       ========================= */

    [data-e2e="root-container"],
    [data-e2e="browse-video"] {
        background: transparent !important;
    }


    /* =========================
       ? SIDEBAR
       ========================= */

    [data-e2e="sidebar-container"] {
        background: rgba(255, 255, 255, 0.78) !important;
        backdrop-filter: blur(12px) !important;
        border-right: 1px solid rgba(155, 123, 232, 0.20) !important;
    }

    [data-e2e="sidebar-item"],
    [data-e2e="nav-home"],
    [data-e2e="nav-following"] {
        color: var(--purple-dark) !important;
    }

    [data-e2e="sidebar-item"]:hover {
        background: rgba(155, 123, 232, 0.12) !important;
        border-radius: 12px !important;
    }


    /* =========================
       ? TEXT
       ========================= */

    body,
    p,
    span,
    a,
    h1,
    h2,
    h3 {
        --text-color: var(--purple-dark);
    }

    a:hover {
        color: var(--purple) !important;
    }


    /* =========================
       ? SEARCH BAR
       ========================= */

    [data-e2e="search-container"],
    [data-e2e="search-input"] {
        background: rgba(255, 255, 255, 0.82) !important;
        border: 1px solid var(--purple-light) !important;
        border-radius: 999px !important;
    }

    [data-e2e="search-input"] {
        color: var(--purple-dark) !important;
    }

    [data-e2e="search-clear"] svg,
    [data-e2e="search-button"] svg {
        fill: var(--purple) !important;
        color: var(--purple) !important;
    }


    /* =========================
       ? BUTTONS
       ========================= */

    button {
        border-radius: 12px !important;
    }

    [data-e2e="top-upload-button"] {
        color: var(--purple-dark) !important;
        border-color: var(--purple-light) !important;
        background: rgba(255, 255, 255, 0.75) !important;
    }

    [data-e2e="top-upload-button"]:hover {
        background: var(--purple-light) !important;
    }


    /* =========================
       ? ICONS
       ========================= */

    svg {
        color: var(--purple) !important;
    }

    [data-e2e="sidebar-item"] svg,
    [data-e2e="search-clear-icon"] svg,
    [data-e2e="more-button"] svg {
        color: var(--purple) !important;
        fill: var(--purple) !important;
    }


    /* =========================
       ? VIDEO AREA
       ========================= */

    [data-e2e="recommend-list-container"] {
        background: rgba(255, 255, 255, 0.18) !important;
        border-radius: 18px !important;
    }

    [data-e2e="feed-video"] {
        border-radius: 18px !important;
        overflow: hidden !important;
        box-shadow:
            0 8px 30px rgba(118, 85, 199, 0.18) !important;
    }


    /* =========================
       ? LIKE / COMMENT / SHARE
       ========================= */

    [data-e2e="like-icon"],
    [data-e2e="comment-icon"],
    [data-e2e="share-icon"],
    [data-e2e="bookmark-icon"] {
        color: var(--purple) !important;
        fill: var(--purple) !important;
    }


    /* =========================
       ? RIGHT SIDE RECOMMENDATIONS
       ========================= */

    [data-e2e="recommend-list"] {
        background: rgba(255, 255, 255, 0.55) !important;
        backdrop-filter: blur(10px) !important;
        border-radius: 18px !important;
    }


    /* =========================
       ? PROFILE / CARDS
       ========================= */

    [data-e2e="user-card"],
    [data-e2e="following-card"] {
        background: rgba(255, 255, 255, 0.65) !important;
        border-radius: 14px !important;
    }

    [data-e2e="user-card"]:hover,
    [data-e2e="following-card"]:hover {
        background: rgba(217, 204, 250, 0.55) !important;
    }


    /* =========================
       ? SCROLLBAR
       ========================= */

    ::-webkit-scrollbar {
        width: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: rgba(155, 123, 232, 0.08) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: var(--purple) !important;
        border-radius: 10px !important;
        border: 2px solid #faf8ff !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: var(--purple-dark) !important;
    }
}
